void Solver::restart() {
    // Reset LBD statistics more aggressively
    fast_lbd_sum = 0;
    slow_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;

    // Backtrack to root level
    backtrack(0);

    // Rephase saved phases with a new strategy
    int r = rand() % 100;
    if (r < 30) {
        // Use the best local assignment found so far
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    } else if (r < 60) {
        // Use the opposite of the best local assignment
        for (int i = 1; i <= vars; i++) saved[i] = -local_best[i];
    } else {
        // Randomly assign phases
        for (int i = 1; i <= vars; i++) saved[i] = (rand() % 2) ? 1 : -1;
    }

    // Reset rephase counters to give the new phases more effect
    rephases = 0;
    rephase_limit += 4096;
}
